const lessons=[
  {level:1,topic:'FILTRER',title:'Le carnet des bonnes ventes',story:'La boutique a enregistré plusieurs commandes. Tu veux regarder seulement celles qui dépassent 400 FC.',question:'Quel code conserve uniquement les ventes au-dessus de 400 ?',correct:"df[df['montant'] > 400]",options:["df[df['montant'] > 400]","df['montant' > 400]","df.sort_values('montant')"],why:'Entre les crochets, pandas attend une condition. Chaque ligne devient True ou False selon son montant.',headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Goma','Café','680'],['Bukavu','Jus','245'],['Matadi','Thé','510']]},
  {level:1,topic:'SÉLECTIONNER',title:'Garde l’essentiel',story:'L’équipe terrain doit recevoir un tableau très simple : seulement la ville et le montant de chaque vente.',question:'Quelle sélection garde ces deux colonnes dans cet ordre ?',correct:"df[['ville', 'montant']]",options:["df[['ville', 'montant']]","df['ville', 'montant']","df['ville'] + df['montant']"],why:'La liste des colonnes se place dans une deuxième paire de crochets. Le résultat reste un DataFrame.',headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Goma','Café','680'],['Bukavu','Jus','245'],['Matadi','Thé','510']]},
  {level:2,topic:'NETTOYER',title:'Une cellule manque à l’appel',story:'Le montant de Goma est absent. Avant de calculer un total, tu décides de remplacer cette absence par 0.',question:'Quelle ligne remplace les valeurs manquantes de montant par 0 ?',correct:"df['montant'] = df['montant'].fillna(0)",options:["df['montant'] = df['montant'].fillna(0)","df['montant'].dropna(0)","df['montant'] == 0"],why:'fillna(0) remplace les valeurs inconnues. Un NaN doit être traité avant de faire confiance à un calcul.',headers:['ville','montant','vendeur'],rows:[['Kinshasa','420','Mia'],['Goma','—','Nora'],['Bukavu','245','Mia'],['Matadi','510','Nora']]},
  {level:2,topic:'TRANSFORMER',title:'La part de commission',story:'Chaque vente génère une commission de 10 %. Ajoute cette nouvelle information au tableau.',question:'Quel code crée correctement la colonne commission ?',correct:"df['commission'] = df['montant'] * 0.1",options:["df['commission'] = df['montant'] * 0.1","df.commission == montant * 0.1","df.add('commission', 0.1)"],why:'Les opérations pandas sont vectorisées : une multiplication de deux colonnes ou d’une colonne par un nombre agit sur chaque ligne.',headers:['ville','montant','commission'],rows:[['Kinshasa','420','?'],['Goma','680','?'],['Bukavu','245','?'],['Matadi','510','?']]},
  {level:3,topic:'RÉSUMER',title:'Le duel des vendeurs',story:'Mia et Nora ont chacune plusieurs ventes. Tu veux savoir qui a généré le montant total le plus élevé.',question:'Quel code calcule un total par vendeur ?',correct:"df.groupby('vendeur')['montant'].sum()",options:["df.groupby('vendeur')['montant'].sum()","df['vendeur'].sum('montant')","df.sum('vendeur', 'montant')"],why:'groupby sépare les lignes en groupes. Ensuite sum() calcule une réponse pour chaque groupe.',headers:['vendeur','montant','ville'],rows:[['Mia','420','Kinshasa'],['Nora','680','Goma'],['Mia','245','Bukavu'],['Nora','510','Matadi']]},
  {level:3,topic:'TRIER',title:'Le podium des ventes',story:'Le responsable veut voir les plus grosses ventes en premier, sans changer les données elles-mêmes.',question:'Quelle instruction trie montant du plus grand au plus petit ?',correct:"df.sort_values('montant', ascending=False)",options:["df.sort_values('montant', ascending=False)","df.sort_values('montant', ascending=True)","df.reverse('montant')"],why:'sort_values trie dans l’ordre croissant par défaut. ascending=False inverse le sens.',headers:['ville','montant'],rows:[['Kinshasa','420'],['Goma','680'],['Bukavu','245'],['Matadi','510']]},
  {level:4,topic:'RELIER',title:'Retrouve les villes',story:'Les ventes utilisent des identifiants de ville. Une seconde table connaît leurs vrais noms. Relie-les sans perdre de vente.',question:'Quelle jointure conserve toutes les lignes de ventes ?',correct:"pd.merge(ventes, villes, how='left', on='ville_id')",options:["pd.merge(ventes, villes, how='left', on='ville_id')","pd.merge(ventes, villes, how='inner')","pd.concat(ventes, villes, on='ville_id')"],why:'Une jointure left conserve toujours les lignes de la table placée à gauche : ici, ventes.',headers:['ville_id','montant','ville'],rows:[['1','420','Kinshasa'],['2','680','Goma'],['3','245','—'],['2','510','Goma']]},
  {level:4,topic:'DATES',title:'Le trimestre caché',story:'Les ventes ont une date. L’équipe finance veut les répartir par trimestre.',question:'Quel code extrait le trimestre depuis une colonne datetime ?',correct:"df['trimestre'] = df['date'].dt.quarter",options:["df['trimestre'] = df['date'].dt.quarter","df['trimestre'] = df['date'].quarter()","df.quarter(df['date'])"],why:'L’accesseur .dt donne accès aux informations temporelles de chaque date, comme le trimestre.',headers:['date','montant','trimestre'],rows:[['2026-01-18','420','?'],['2026-04-02','680','?'],['2026-09-11','245','?'],['2026-12-27','510','?']]},
  {level:5,topic:'TEXTE',title:'Les noms désordonnés',story:'Les produits sont saisis avec des casses différentes. Tu veux rendre la liste plus agréable à lire.',question:'Quelle ligne met une majuscule à chaque mot de produit ?',correct:"df['produit'] = df['produit'].str.title()",options:["df['produit'] = df['produit'].str.title()","df.title('produit')","df['produit'].title"],why:'Les opérations de texte pandas passent par .str. Elles s’appliquent à toute la colonne, pas à une seule cellule.',headers:['produit','montant'],rows:[['café noir','420'],['THÉ VERT','680'],['jus mangue','245'],['CAFE LATTE','510']]},
  {level:5,topic:'PIPELINE',title:'La vue finale',story:'Tu veux finalement garder les ventes importantes, puis les classer de la plus forte à la plus faible.',question:'Quel pipeline fait ces deux actions dans le bon ordre ?',correct:"df.query('montant > 400').sort_values('montant', ascending=False)",options:["df.query('montant > 400').sort_values('montant', ascending=False)","df.sort_values('montant').query('montant > 400')","df.filter('montant > 400').reverse()"],why:'Une chaîne de méthodes décrit un chemin de lecture : filtrer d’abord, trier ensuite.',headers:['ville','montant','produit'],rows:[['Kinshasa','420','Thé'],['Goma','680','Café'],['Bukavu','245','Jus'],['Matadi','510','Thé']]}
];
const $=id=>document.getElementById(id);const state=JSON.parse(localStorage.getItem('pandasQuestPlay')||'{"current":0,"xp":0,"solved":[]}');let current=Math.min(state.current||0,lessons.length-1),selected=null,checked=false;
function renderTable(lesson){$('dataSize').textContent=`${lesson.rows.length} lignes`;$('dataTable').innerHTML=`<table><thead><tr>${lesson.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${lesson.rows.map(r=>`<tr>${r.map((cell,i)=>`<td class="${i===lesson.headers.length-1?'num':''}">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function renderSegments(){const level=lessons[current].level;$('segments').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i+1<level?'done':i+1===level?'active':''}"></i>`).join('');}
function setExplanation(kind,text){const box=$('explanation');box.className=`explanation ${kind||''}`;$('explanationIcon').textContent=kind==='correct'?'✓':kind==='wrong'?'!':'✦';$('explanationText').textContent=text;}
function renderChoices(){const lesson=lessons[current];$('choices').innerHTML=lesson.options.map((option,index)=>`<button class="choice ${selected===index?'selected':''}" data-option="${index}" role="radio" aria-checked="${selected===index}"><span class="radio"></span><code>${option}</code></button>`).join('');document.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>{if(checked)return;selected=Number(button.dataset.option);$('submitBtn').disabled=false;renderChoices();setExplanation('','Réponse choisie. Valide pour voir l’explication.');}));}
function render(){const lesson=lessons[current];selected=null;checked=false;$('eyebrow').textContent=`NIVEAU ${lesson.level} · ${lesson.topic}`;$('title').textContent=lesson.title;$('story').textContent=lesson.story;$('questionNumber').textContent=`DÉFI ${current+1} · ${lessons.length}`;$('question').textContent=lesson.question;$('xpValue').textContent=state.xp;const submit=$('submitBtn');submit.textContent='Valider';submit.disabled=true;submit.classList.remove('continue');renderSegments();renderTable(lesson);renderChoices();setExplanation('','Sélectionne une réponse pour continuer.');}
function save(){state.current=current;localStorage.setItem('pandasQuestPlay',JSON.stringify(state));}
function validate(){const lesson=lessons[current];if(selected===null)return;if(checked){next();return}checked=true;const buttons=[...document.querySelectorAll('.choice')];const correctIndex=lesson.options.indexOf(lesson.correct);buttons[correctIndex].classList.add('correct');if(selected===correctIndex){if(!state.solved.includes(current)){state.solved.push(current);state.xp+=10;save();}$('xpValue').textContent=state.xp;setExplanation('correct',lesson.why);$('submitBtn').textContent=current===lessons.length-1?'Rejouer le parcours':'Continuer';$('submitBtn').classList.add('continue');toast('+10 XP · Défi réussi');}else{buttons[selected].classList.add('wrong');setExplanation('wrong','Pas tout à fait. '+lesson.why);$('submitBtn').textContent='Réessayer';$('submitBtn').classList.remove('continue');$('submitBtn').disabled=true;checked=false;selected=null;}}
function next(){if(current===lessons.length-1){current=0;toast('Parcours bouclé : repars pour ancrer tes réflexes.')}else current++;save();render();window.scrollTo({top:0,behavior:'smooth'});}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
$('submitBtn').addEventListener('click',validate);$('whyBtn').addEventListener('click',()=>{setExplanation('',lessons[current].why);});$('restartBtn').addEventListener('click',()=>{if(confirm('Recommencer depuis le premier défi ?')){state.current=0;state.xp=0;state.solved=[];save();render();}});render();
